 IEnumerator LayoutMatrix(){
  records.Add("Layout/state fixtures use injected names and modal state, not match-outcome evidence.");
  var sizes=new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080),new Vector2Int(1600,1000),new Vector2Int(1280,960),new Vector2Int(2560,1080)};
  foreach(var size in sizes){Screen.SetResolution(size.x,size.y,FullScreenMode.Windowed);yield return Wait(()=>Screen.width==size.x&&Screen.height==size.y,8,"resolution "+size);yield return Delay(.2f);
   foreach(var sport in new[]{SportsNavigation.Billiards,SportsNavigation.Hockey,SportsNavigation.AirHockey,SportsNavigation.Wallball}){
    SportsNavigation.LoadSport(sport);yield return Delay(.4f);string label=sport+"-"+size.x+"x"+size.y;
    if(sport==SportsNavigation.Billiards){var m=FindAnyObjectByType<BilliardsMatch>();m.session.SelectMode(BilliardsMode.SharedKeyboard);for(int i=0;i<2;i++)m.session.players[i].name=i==0?"Alexandra Montgomery":"Christopher Harrington";m.session.StartMatch();}
    else if(sport==SportsNavigation.Hockey){var m=FindAnyObjectByType<HockeyMatch>();m.mode=HockeyMode.AIVsAI;m.Configure();for(int i=0;i<6;i++)m.players[i].name=(i<3?"Alexandra Montgomery ":"Christopher Harrington ")+(i%3+1);m.StartMatch();}
    else if(sport==SportsNavigation.AirHockey){var m=FindAnyObjectByType<AirHockeyMatch>();m.Configure(AirHockeyMode.AIVsAI);m.players[0].name="Alexandra Montgomery";m.players[1].name="Christopher Harrington";m.StartMatch();}
    else{var m=FindAnyObjectByType<WallballMatch>();m.Configure(WallballMode.AIVsAI);m.players[0].name="Alexandra Montgomery";m.players[1].name="Christopher Harrington";m.StartMatch();}
    yield return Delay(.25f);var fit=FindAnyObjectByType<SportsCameraFit>();fit.Apply();yield return null;var projected=SportsCameraFit.Projected(fit.cameraTarget,fit.arenaBounds);Check(projected.xMin>=-.001f&&projected.xMax<=1.001f&&projected.yMin>=-.001f&&projected.yMax<=1.001f,"complete arena volume fits "+label);records.Add("LAYOUT "+label+" projected="+projected+" ortho="+fit.cameraTarget.orthographicSize);
    foreach(var overlay in FindObjectsByType<SportsArenaOverlay>(FindObjectsInactive.Exclude)){foreach(var dock in overlay.docks){if(!dock.target.gameObject.activeInHierarchy)continue;var text=dock.target.GetComponent<TMP_Text>();text.ForceMeshUpdate();var corners=new Vector3[4];dock.plate.GetWorldCorners(corners);foreach(var p in corners){var screen=RectTransformUtility.WorldToScreenPoint(null,p);Check(screen.x>=-2&&screen.x<=Screen.width+2&&screen.y>=-2&&screen.y<=Screen.height+2,"HUD within screen "+label+" "+text.name);}Check(!text.isTextTruncated,"long name/state readable "+label+" "+text.name);}}
    yield return Capture("layout-"+label);
    if(sport==SportsNavigation.Billiards){var m=FindAnyObjectByType<BilliardsMatch>();m.session.Pause();}else if(sport==SportsNavigation.Hockey)FindAnyObjectByType<HockeyMatch>().Pause();else if(sport==SportsNavigation.AirHockey)FindAnyObjectByType<AirHockeyMatch>().Pause();else FindAnyObjectByType<WallballMatch>().Pause();yield return Delay(.15f);yield return Capture("pause-"+label);
    if(sport==SportsNavigation.Wallball){var m=FindAnyObjectByType<WallballMatch>();m.Resume();m.ball.body.position=new Vector3(7,8.5f,-18);m.ball.body.linearVelocity=new Vector3(-3,1,5);Physics.SyncTransforms();yield return Delay(.08f);var viewport=fit.cameraTarget.WorldToViewportPoint(m.ball.body.position);Check(viewport.x>0&&viewport.x<1&&viewport.y>0&&viewport.y<1,"high rebound fixture visible "+label);yield return Capture("high-flight-"+label);}
    SportsNavigation.FrontEnd();yield return Delay(.3f);Check(FindAnyObjectByType<SportsFrontEnd>()!=null&&FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length==1&&FindObjectsByType<UnityEngine.EventSystems.EventSystem>(FindObjectsInactive.Include).Length==1,"clean return "+label);
   }
  }
 }
 IEnumerator BowlingCarry(){yield return EnterBowling();var m=FindAnyObjectByType<BowlingMatch>();records.Add("Physical spinout fixtures seed poses/velocities; no injected pinfall or score. W remains held until pit or bounded genuine recovery.");foreach(var kind in new[]{"normal","sideways","backward","gutter"}){
  Keys();m.PresetAI(1,BowlingMode.Simultaneous);m.setup.players[0].source=BowlingSource.Keyboard;Check(m.StartMatch(),"carry start "+kind);yield return Delay(.3f);var l=m.lanes[0];var t=l.truck;int locks=l.ScoreLocks;float x=kind=="gutter"?2.3f:0;float yaw=kind=="sideways"?90:kind=="backward"?180:0;var p=new Vector3(l.center+x,.26f,22);var q=Quaternion.Euler(0,yaw,0);t.transform.SetPositionAndRotation(p,q);t.body.position=p;t.body.rotation=q;t.body.linearVelocity=new Vector3(0,0,10);t.body.angularVelocity=kind=="normal"?Vector3.zero:new Vector3(0,.8f,0);Physics.SyncTransforms();Keys(Key.W);float end=Time.realtimeSinceStartup+35;bool gutter=false,pit=false,legal=false;float maxZ=22,maxCarry=0;string reason="";var pitShape=l.transform.Find("Pit").GetComponent<Collider>();
  while(l.ScoreLocks==locks){if(Time.realtimeSinceStartup>end)throw new Exception("carry delivery timeout "+kind);maxZ=Mathf.Max(maxZ,t.body.position.z);maxCarry=Mathf.Max(maxCarry,t.CarryAcceleration);gutter|=l.Gutter;legal|=l.LegalPinContact;if(t.body.position.z>l.pinLine+7.4f)pit=true;foreach(var wheel in t.wheels)if(wheel.IsGrounded&&wheel.HitCollider==pitShape)pit=true;if(l.Phase==BowlingPhase.Rolling){CheckSilent(!t.body.isKinematic,"live carry froze "+kind);if(kind=="gutter")CheckSilent(l.Gutter&&Mathf.Abs(t.body.position.x-l.center)>l.halfWidth,"gutter rescued "+kind);}if(l.Phase==BowlingPhase.Settling){reason=l.Result;CheckSilent(pit||reason.Contains("recovery")||reason.Contains("limit"),"premature delivery transition "+kind);if(reason=="END PIT")CheckSilent(!t.body.isKinematic,"pit settling clears momentum early "+kind);}yield return null;}
  records.Add("CARRY "+kind+" maxZ="+maxZ.ToString("F2")+" pit="+pit+" gutter="+gutter+" pins="+l.LastPins+" physical="+legal+" maxAssist="+maxCarry.ToString("F3")+" recovery="+reason);Check(pit,"spinout reaches end pit "+kind);Check(maxCarry<=t.handling.carryAcceleration+.001f,"carry bounded "+kind);if(kind=="gutter")Check(gutter&&l.LastPins==0,"committed gutter yields zero "+kind);if(l.LastPins>0)Check(legal,"physical pinfall provenance "+kind);Check(l.ScoreLocks==locks+1,"score locked once "+kind);yield return Capture("carry-pit-"+kind);Keys();m.ChangeSetup();}
 }
 void CheckSilent(bool value,string name){if(!value)throw new Exception(name);}
 IEnumerator VisualChecks(){SportsNavigation.LoadSport(SportsNavigation.Billiards);yield return Delay(.5f);var m=FindAnyObjectByType<BilliardsMatch>();m.session.SelectMode(BilliardsMode.Practice);m.session.hotSeatGamepad=false;m.session.SelectMode(BilliardsMode.Practice);m.session.StartMatch();yield return Delay(1.2f);foreach(var b in m.balls)if(b.number!=0&&b.number!=9)b.SetPocketed(true);var ball=m.balls[9];ball.Restore(new Vector3(-2,.5f,-3));yield return Delay(.1f);var display=ball.presentation;Check(display!=null&&ball.GetComponentsInChildren<Collider>().Length==1,"visual sphere and shadow have no added collider");var origin=ball.transform.position;var start=display.visual.rotation;ball.body.linearVelocity=new Vector3(2,0,0);yield return Delay(.18f);float distance=Vector3.Distance(origin,ball.transform.position),actual=Quaternion.Angle(start,display.visual.rotation),expected=distance/display.radius*Mathf.Rad2Deg;Check(Mathf.Abs(actual-expected)<3&&display.RollSteps>0,"straight visible rolling matches distance/radius actual="+actual+" expected="+expected);yield return Capture("visual-straight");ball.body.linearVelocity=Vector3.zero;yield return Delay(.12f);var stopped=display.visual.rotation;yield return Delay(.25f);Check(Quaternion.Angle(stopped,display.visual.rotation)<.02f,"stopped ball stops rotating");ball.Restore(new Vector3(4.8f,.5f,-4));ball.body.linearVelocity=new Vector3(3,0,0);yield return Wait(()=>ball.body.linearVelocity.x<-.2f,2,"real cushion rebound");yield return Capture("visual-rebound");Check(Quaternion.Angle(ball.body.rotation,Quaternion.identity)<.01f,"no physical angular double rotation");
  m.session.RestartRack();yield return Delay(.15f);foreach(var b in m.balls)Check(!b.Pocketed&&b.presentation.visual.gameObject.activeSelf&&Mathf.Abs(b.presentation.visual.localPosition.y)<.001f&&Quaternion.Angle(b.presentation.visual.localRotation,b.presentation.rackRotation)<.1f,"rack restores sphere "+b.number);
  yield return Wait(()=>m.AreSettled,3,"placement settle");m.session.RepositionCue();var target=new Vector3(-2,.5f,-4);var mouse=InputSystem.AddDevice<Mouse>("Polish placement software pointer");var screen=m.tableCamera.WorldToScreenPoint(target);InputSystem.QueueStateEvent(mouse,new MouseState{position=new Vector2(screen.x,screen.y)});yield return Delay(.2f);Check(m.placementValid&&Vector3.Distance(m.placementPosition,target)<.03f,"mouse-to-table mapping after framing");yield return Capture("visual-cue-placement");InputSystem.QueueStateEvent(mouse,new MouseState{position=new Vector2(screen.x,screen.y)}.WithButton(MouseButton.Left));yield return Delay(.1f);InputSystem.QueueStateEvent(mouse,new MouseState{position=new Vector2(screen.x,screen.y)});yield return Delay(.15f);Check(m.rules.Phase==MatchPhase.Aiming&&Vector3.Distance(m.balls[0].body.position,target)<.03f,"actual pointer confirms cue placement");InputSystem.RemoveDevice(mouse);Check(Quaternion.Angle(m.balls[0].presentation.visual.localRotation,m.balls[0].presentation.rackRotation)<.1f,"cue teleport does not roll giant displacement");
  ball=m.balls[9];display=ball.presentation;m.rules.BeginShot();ball.Restore(new Vector3(5,.5f,0));ball.body.linearVelocity=new Vector3(2,0,0);yield return Wait(()=>ball.Pocketed,2,"real pocket crossing");int drops=display.Drops;m.Pocket(ball);Check(display.Drops==drops&&ball.body.isKinematic&&!ball.sphere.enabled,"pocket awarded once and animation noncolliding");yield return Delay(.15f);Check(display.Dropping&&display.visual.gameObject.activeSelf&&display.visual.localPosition.y<-.1f,"visible downward pocket drop");yield return Capture("visual-pocket-mid-drop");yield return Delay(.3f);Check(!display.visual.gameObject.activeSelf,"drop completes without scoring delay");m.session.RestartRack();yield return Delay(.1f);Check(!ball.Pocketed&&display.visual.gameObject.activeSelf&&!display.Dropping,"pocket visuals restore on rack reset");
  m.session.SelectMode(BilliardsMode.SharedKeyboard);m.session.StartMatch();m.rules.BeginShot();m.rules.Contact(1);m.rules.Pocket(1,1);m.rules.Pocket(9,2);m.rules.Resolve();m.session.ShotResolved(0);yield return Delay(.15f);Check(m.session.Screen==BilliardsScreen.GroupSelection,"group-choice modal intact");yield return Capture("visual-group-choice");m.session.Pause();yield return Capture("visual-pause");
 }
 IEnumerator FixedOutcomeComparison(){
  records.Add("Authoritative A/B uses a fresh local physics scene for every shot, existing saved bodies/ball/match FixedUpdate, fixed .02s steps. A repeated disabled run tests the oracle before presentation-enabled comparison; no contact-cache reuse.");SportsNavigation.FrontEnd();yield return Delay(.4f);var reference=new List<string>();
  for(int mode=0;mode<3;mode++)for(int shot=0;shot<3;shot++){
   var operation=UnityEngine.SceneManagement.SceneManager.LoadSceneAsync(SportsNavigation.Billiards,new UnityEngine.SceneManagement.LoadSceneParameters(UnityEngine.SceneManagement.LoadSceneMode.Additive,UnityEngine.SceneManagement.LocalPhysicsMode.Physics3D));while(!operation.isDone)yield return null;yield return Delay(.2f);var scene=UnityEngine.SceneManagement.SceneManager.GetSceneByName(SportsNavigation.Billiards);BilliardsMatch m=null;foreach(var root in scene.GetRootGameObjects()){if(root.TryGetComponent<BilliardsMatch>(out var found))m=found;foreach(var script in root.GetComponentsInChildren<MonoBehaviour>(true))script.enabled=script is BilliardsBallPresentation&&mode==2;foreach(var camera in root.GetComponentsInChildren<Camera>(true))camera.enabled=false;foreach(var listener in root.GetComponentsInChildren<AudioListener>(true))listener.enabled=false;}Check(m!=null,"fresh saved match for physical comparison");m.session.SelectMode(BilliardsMode.Practice);m.session.StartMatch();Time.timeScale=0;var physics=scene.GetPhysicsScene();Physics.SyncTransforms();for(int step=0;step<60;step++){foreach(var b in m.balls)b.SendMessage("FixedUpdate");m.SendMessage("FixedUpdate");physics.Simulate(.02f);}Check(m.AreSettled,"fixed comparison rack settled");m.Strike(m.player,new Vector3((shot-1)*1.3f,0,13));int loops=0;while(m.resolutionCount==0){if(loops++>3000)throw new Exception("fixed shot failed to settle");foreach(var b in m.balls)b.SendMessage("FixedUpdate");m.SendMessage("FixedUpdate");physics.Simulate(.02f);if(loops%25==0)yield return null;}string state="shot="+shot+" steps="+loops+" turn="+m.rules.Turn+" reason="+m.rules.Notice;foreach(var b in m.balls)state+=" | "+b.number+":"+b.Pocketed+":"+b.body.position.ToString("F4");records.Add("FIXED_OUTCOME visual="+(mode==2)+" repeat="+mode+" "+state);if(mode==0)reference.Add(state);else Check(state==reference[shot],(mode==1?"disabled oracle repeats":"identical authoritative outcome with rolling/drop enabled")+" shot="+shot);var unload=UnityEngine.SceneManagement.SceneManager.UnloadSceneAsync(scene);while(!unload.isDone)yield return null;Time.timeScale=1;
  }
 }
 IEnumerator RenderPerformance(){SportsNavigation.LoadSport(SportsNavigation.Billiards);yield return Delay(.6f);var m=FindAnyObjectByType<BilliardsMatch>();m.session.SelectMode(BilliardsMode.Practice);m.session.StartMatch();yield return Delay(1.2f);records.Add("Sustained rendering fixture, 30 seconds per mode at timeScale=1. Off removes new sphere/shadow rendering only; not an old-flat-label build benchmark. Concurrent user applications are left running.");for(int mode=0;mode<2;mode++){foreach(var b in m.balls){foreach(var r in b.presentation.GetComponentsInChildren<MeshRenderer>())if(r.transform!=b.transform)r.enabled=mode==1;b.body.linearVelocity=new Vector3((b.number%3-1)*.7f,0,(b.number%2==0?1:-1)*.8f);}yield return Delay(1);frameSamples.Clear();long memory=GC.GetTotalMemory(false);int gc=GC.CollectionCount(0);float until=Time.realtimeSinceStartup+30;while(Time.realtimeSinceStartup<until){frameSamples.Add(Time.unscaledDeltaTime);yield return null;}frameSamples.Sort();double sum=0;foreach(float sample in frameSamples)sum+=sample;records.Add("RENDER_PERF enabled="+mode+" seconds=30 frames="+frameSamples.Count+" meanMs="+(sum/frameSamples.Count*1000).ToString("F2")+" p95Ms="+(frameSamples[(int)(frameSamples.Count*.95f)]*1000).ToString("F2")+" p99Ms="+(frameSamples[(int)(frameSamples.Count*.99f)]*1000).ToString("F2")+" managedDelta="+(GC.GetTotalMemory(false)-memory)+" gen0="+(GC.CollectionCount(0)-gc));yield return Capture("render-perf-"+mode);}records.Add("ENVIRONMENT GPU="+SystemInfo.graphicsDeviceName+" API="+SystemInfo.graphicsDeviceType+" size="+Screen.width+"x"+Screen.height+" vsync="+QualitySettings.vSyncCount+" frameCap="+Application.targetFrameRate);Check(!failed,"sustained sphere/UI rendering clean");}
